// Krunker's official map table (shared/include/krunker_maps.h, generated by tools/krunker/maps.py from
// tools/krunker/maps.lock.json) and the map resolution of an official game (client/src/net/
// krunker_map_source.c): every index loads and plays, inline custom maps are cached by id, an index
// past the table comes from the cache or GET <API>/maps/<index>, the unknown is reported.
//   cmake-build-debug/krunker_maps_test        (from the repository root: assets/)
#include <krunker_map_source.h>
#include <krunker_maps.h>
#include <map_catalog.h>
#include <shared.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// setenv for MinGW, whose CRT has only _putenv_s (the same guard as client/src/headless.c).
static int test_setenv(const char *name, const char *value, const int overwrite) {
#ifdef _WIN32
    if (!overwrite && getenv(name)) return 0;
    return _putenv_s(name, value);
#else
    return setenv(name, value, overwrite);
#endif
}

static int g_fail, g_pass;
#define CHECK(cond, ...) do { if (cond) g_pass++; else { g_fail++; printf("FAIL %s:%d: ", __FILE__, __LINE__); printf(__VA_ARGS__); printf("\n"); } } while (0)

static const char *k_tiny_map =
    "{\"name\":\"Tiny\",\"spawns\":[[0,0,0,0,0,0]],\"objects\":[{\"p\":[0,-10,0],\"s\":[200,10,200]}]}";

// ---- the network double: one GET in flight, answered by the test
static struct {
    char url[512];
    KrunkerMapFetchDone done;
    void *ctx;
    int calls;
    int refuse;
} g_net;

static int fake_fetch(const char *url, KrunkerMapFetchDone done, void *ctx) {
    g_net.calls++;
    if (g_net.refuse) return 0;
    snprintf(g_net.url, sizeof(g_net.url), "%s", url);
    g_net.done = done;
    g_net.ctx = ctx;
    return 1;
}

static void answer(const int status, const char *body) {
    KrunkerMapFetchDone done = g_net.done;
    g_net.done = NULL;
    if (done) done(g_net.ctx, status, body, body ? strlen(body) : 0);
}

static KrunkerMapStatus resolve(const int index, const char *custom_text, const char *id, const cJSON **out, char *why, size_t n) {
    KrunkerMapRequest r;
    krunker_map_request_begin(&r, index, custom_text ? cJSON_Parse(custom_text) : NULL, id);
    KrunkerMapStatus st;
    int polls = 0;
    while ((st = krunker_map_request_poll(&r, out, why, n)) == KRUNKER_MAP_PENDING && ++polls < 4) {}
    if (st == KRUNKER_MAP_PENDING) krunker_map_request_cancel(&r);
    return st;
}

static int file_exists(const char *dir, const char *name) {
    char path[1200];
    snprintf(path, sizeof(path), "%s/%s", dir, name);
    FILE *f = fopen(path, "rb");
    if (f) fclose(f);
    return f != NULL;
}

// every table map: map_init builds it (objects, spawns); then one game_init round on each
static void test_table(void) {
    CHECK(krunker_official_map_count() == KRUNKER_OFFICIAL_MAP_COUNT && KRUNKER_OFFICIAL_MAP_COUNT >= 46,
          "the official list has %d maps", KRUNKER_OFFICIAL_MAP_COUNT);
    CHECK(!strcmp(krunker_official_map_name(43), "Bastion"), "map 43 is Bastion (%s)", krunker_official_map_name(43));
    CHECK(!strcmp(krunker_official_map_name(KRUNKER_OFFICIAL_MAP_COUNT - 1), "Barnyard"), "the highest map is Barnyard (%s)",
          krunker_official_map_name(KRUNKER_OFFICIAL_MAP_COUNT - 1));
    CHECK(!krunker_official_map_name(KRUNKER_OFFICIAL_MAP_COUNT) && !krunker_official_map_name(-1) && !krunker_official_map_file(-1),
          "outside the table: NULL");
    // our catalogue's official maps are Krunker's 46, by mapIndex (the v10.0.2 list; 0..31 are v7.1.4's)
    for (int i = 0; i < MAP_CATALOG_OFFICIAL_COUNT; i++) {
        const int at = map_catalog_official_index(i);
        CHECK(at >= 0 && !strcmp(map_catalog_at((size_t) at)->name, krunker_official_map_name(i)), "map %d: catalogue %s, Krunker %s", i,
              at >= 0 ? map_catalog_at((size_t) at)->name : "none", krunker_official_map_name(i));
    }
    const cJSON *maps[KRUNKER_OFFICIAL_MAP_COUNT];
    for (int i = 0; i < KRUNKER_OFFICIAL_MAP_COUNT; i++) {
        const cJSON *json = krunker_official_map_json(i);
        maps[i] = json;
        CHECK(json != NULL, "map %d (%s): %s does not load", i, krunker_official_map_name(i), krunker_official_map_file(i));
        if (!json) continue;
        CHECK(krunker_official_map_json(i) == json, "map %d: cached", i);
        Map *map = map_init(json);
        CHECK(map && map->object_count > 0 && map->spawn_count > 0, "map %d (%s): map_init (%zu objects, %zu spawns)", i,
              krunker_official_map_name(i), map ? map->object_count : 0, map ? map->spawn_count : 0);
        if (map) {
            printf("  %2d %-18s %-38s objects %4zu spawns %3zu\n", i, krunker_official_map_name(i), krunker_official_map_file(i),
                   map->object_count, map->spawn_count);
            map_fini(map);
            free(map);
        }
    }
    static Game game;
    const cJSON **list = calloc(KRUNKER_OFFICIAL_MAP_COUNT, sizeof(*list));
    size_t n = 0;
    for (int i = 0; i < KRUNKER_OFFICIAL_MAP_COUNT; i++) if (maps[i]) list[n++] = maps[i];
    game_configure(&game, NULL, list, n, NULL, 0, NULL, 0, NULL, 0); // the game owns `list`
    for (size_t i = 0; i < n; i++) {
        game_init(&game, (int) i, 0, 0);
        CHECK(game.ready && game.map && game.map->spawn_count > 0, "game_init on map %zu (%s)", i, krunker_official_map_name((int) i));
    }
}

// The table's object count is the v10 file's (maps.lock.json "objects", the JSON the live server plays)
#define KMT_OBJECTS(index_, name_, file_, objects_) objects_,
static const int k_table_objects[] = {KRUNKER_OFFICIAL_MAPS(KMT_OBJECTS)};

// Every spawn of every official map is where the live server puts a player (it plays the same v10 file):
// standing there with no input, our collision world must hold the player up (on the ground, not falling
// through to the death plane). A spawn over nothing here is the "spawned in the middle of nowhere" desync.
// The maps an earlier audit flagged (Tortuga 18, Krunk_Plaza 20, Laboratory 29, Soul Sanctum 31) and the
// ones v7.1.4 lacked (32+) are printed one per line.
static void test_spawns(void) {
    static Game game;
    Player *player = NULL;
    for (int i = 0; i < KRUNKER_OFFICIAL_MAP_COUNT; i++) {
        const cJSON *json = krunker_official_map_json(i);
        if (!json) continue; // test_table reported it
        const int objects = cJSON_GetArraySize(cJSON_GetObjectItemCaseSensitive(json, "objects"));
        CHECK(objects == k_table_objects[i], "map %d (%s): %d objects in %s, the v10 list says %d", i, krunker_official_map_name(i), objects,
              krunker_official_map_file(i), k_table_objects[i]);
        const cJSON **list = calloc(1, sizeof(*list));
        list[0] = json;
        game.map_count = 0; // game_configure frees a previous list
        game_configure(&game, NULL, list, 1, NULL, 0, NULL, 0, NULL, 0);
        game_init(&game, 0, -1, 1);
        if (!game.ready || !game.map) {
            CHECK(0, "map %d: game_init", i);
            continue;
        }
        if (!player) player = player_init(&game);
        if (!game.player_count) game_players_add(&game, player);
        int landed = 0;
        float worst = 0.0f;
        for (size_t s = 0; s < game.map->spawn_count; s++) {
            const vec3 at = game.map->spawns[s]->position;
            player_spawn(player);
            player->position = at;
            player->velocity = (vec3) {0};
            player->swap_timer = 0.0f;
            Input idle = {0};
            idle.move_dir = -1;
            idle.delta = 1000.0f / 60.0f / 1000.0f;
            float y_before = 0.0f;
            for (int t = 0; t < 150; t++) {
                if (t == 120) y_before = player->position.y;
                player_proc_input(player, &idle, 0, 0);
            }
            const float drop = at.y - player->position.y;
            if (drop > worst) worst = drop;
            // held up (standing, or resting on a ramp's edge: SkyTemple's spawn 3 sits on one, on_ground 0),
            // still for the last half second, above the death plane; a spawn set in the air lands on what is
            // under it (Arena's spawn 8 drops 41 onto its platform, the same in v7.1.4's file)
            const int still = fabsf(player->position.y - y_before) < 0.05f;
            const int ok = still && drop < 60.0f && player->position.y > game.map->death_y;
            landed += ok;
            CHECK(ok, "map %d (%s) spawn %zu at %.1f,%.1f,%.1f: after 2.5 s idle at %.1f,%.1f,%.1f (moved %.2f in the last 0.5 s), on_ground %d "
                  "(death_y %.0f)", i, krunker_official_map_name(i), s, at.x, at.y, at.z, player->position.x, player->position.y,
                  player->position.z, player->position.y - y_before, player->on_ground, game.map->death_y);
        }
        CHECK(game.map->spawn_count > 0, "map %d: no spawns", i);
        // HQ (34, refused before): from its spawn 4 (the one krunker_official_e2e.py's native-hq run uses), W
        // with a fresh yaw walks -Z along open floor (spawns 0 and 1 face a crate 2.5 away)
        if (i == 34 && game.map->spawn_count > 4) {
            const vec3 at = game.map->spawns[4]->position;
            player_spawn(player);
            player->position = at;
            player->velocity = (vec3) {0};
            Input in = {0};
            in.delta = 1.0f / 60.0f;
            for (int t = 0; t < 240; t++) {
                in.move_dir = t >= 60 ? 0 : -1; // forward (moveDir 0) after a second standing
                player_proc_input(player, &in, 0, 0);
            }
            CHECK(at.z - player->position.z > 50.0f && fabsf(player->position.y - at.y) < 0.5f && player->on_ground,
                  "HQ spawn 4 (%.0f,%.0f,%.0f): 3 s of W walks on the floor to %.1f,%.1f,%.1f", at.x, at.y, at.z, player->position.x,
                  player->position.y, player->position.z);
        }
        if (i == 18 || i == 20 || i == 29 || i == 31 || i >= 32) { // 32..45: the v10.0.2 additions
            printf("  spawns %2d %-18s objects %4d (v10 list %4d), %zu/%zu spawns stand on solid ground (largest settle %.2f)\n", i,
                   krunker_official_map_name(i), objects, k_table_objects[i], (size_t) landed, game.map->spawn_count, worst);
        }
    }
}

// An official game's map lands in a slot of the client's own list (krunker_net.c kmap_tick: client_map_list_add,
// INIT carries the slot), never at mapIndex itself: the client's list is the 24-map rotation, after a startup
// map when one was given, so slot k is not Krunker's map k (Burg lobby: mapIndex 0; Krunk_Plaza 20 is rotation
// slot 20 = Old_Burg).
static void test_slot_not_index(void) {
    const cJSON *old_burg = krunker_official_map_json(24);
    size_t count = 0;
    const cJSON **list = map_list_with_custom(old_burg, &count); // a startup map first, then the rotation
    CHECK(list && count > 21, "the client's startup list (%zu maps)", count);
    if (!list || count <= 21) return;
    const cJSON *name0 = cJSON_GetObjectItemCaseSensitive(list[0], "name"), *name21 = cJSON_GetObjectItemCaseSensitive(list[21], "name");
    CHECK(strcmp(cJSON_GetStringValue(name0), "Burg") != 0 && !strcmp(cJSON_GetStringValue(name21), "Old_Burg"),
          "the client's slots 0 / 21 are %s / %s, not Krunker's 0 / 21 (what indexing by mapIndex loaded)", cJSON_GetStringValue(name0),
          cJSON_GetStringValue(name21));
    const cJSON *out = NULL;
    char why[256] = "";
    KrunkerMapRequest r;
    krunker_map_request_begin(&r, 0, NULL, "");
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_READY && out == krunker_official_map_json(0), "Burg: %s", why);
    const cJSON **grown = realloc((void *) list, (count + 1) * sizeof(*grown));
    if (!grown || !out) {
        free((void *) (grown ? grown : list));
        return;
    }
    grown[count] = out; // client_map_list_add
    static Game game;
    game.map_count = 0;
    game_configure(&game, NULL, grown, count + 1, NULL, 0, NULL, 0, NULL, 0);
    game_init(&game, (int) count, 0, 0);
    const cJSON *name = game.map ? cJSON_GetObjectItemCaseSensitive(game.map->raw_data, "name") : NULL;
    CHECK(game.ready && name && !strcmp(cJSON_GetStringValue(name), "Burg") && cJSON_GetArraySize(cJSON_GetObjectItem(game.map->raw_data, "objects")) == k_table_objects[0],
          "a Burg lobby (mapIndex 0) plays Burg from %s in slot %zu (%s)", krunker_official_map_file(0), count, name ? cJSON_GetStringValue(name) : "?");
}

static void test_requests(const char *cache) {
    const cJSON *out = NULL;
    char why[256];

    // 2. the table (43 and the highest index)
    CHECK(resolve(43, NULL, "", &out, why, sizeof(why)) == KRUNKER_MAP_READY && out == krunker_official_map_json(43), "request 43: %s", why);
    const int top = KRUNKER_OFFICIAL_MAP_COUNT - 1;
    CHECK(resolve(top, NULL, "", &out, why, sizeof(why)) == KRUNKER_MAP_READY && out == krunker_official_map_json(top), "request %d: %s", top, why);
    CHECK(g_net.calls == 0, "table maps never touch the network");

    // 1. a custom game's inline map: used, cached under its id; 3. the id alone finds it again
    CHECK(resolve(0, k_tiny_map, "123456", &out, why, sizeof(why)) == KRUNKER_MAP_READY && out &&
          !strcmp(cJSON_GetStringValue(cJSON_GetObjectItem(out, "name")), "Tiny"), "inline custom map: %s", why);
    const cJSON *tiny = out;
    CHECK(file_exists(cache, "custom_123456.json"), "inline custom map cached as custom_123456.json in %s", cache);
    CHECK(resolve(0, NULL, "123456", &out, why, sizeof(why)) == KRUNKER_MAP_READY && out == tiny, "custom map by id (memory): %s", why);
    // a cache file from an earlier run
    char path[1200];
    snprintf(path, sizeof(path), "%s/custom_987.json", cache);
    FILE *f = fopen(path, "wb");
    if (f) {
        fputs(k_tiny_map, f);
        fclose(f);
    }
    CHECK(resolve(5, NULL, "987", &out, why, sizeof(why)) == KRUNKER_MAP_READY && out && out != tiny, "custom map by id (cache file): %s", why);
    CHECK(resolve(5, NULL, "nosuchmap", &out, why, sizeof(why)) == KRUNKER_MAP_UNKNOWN && strstr(why, "nosuchmap"), "unknown custom id: %s", why);
    CHECK(resolve(0, "{\"name\":\"x\"}", "55", &out, why, sizeof(why)) == KRUNKER_MAP_UNKNOWN && strstr(why, "not a map"), "custom data that is no map: %s", why);
    CHECK(resolve(0, k_tiny_map, "../evil", &out, why, sizeof(why)) == KRUNKER_MAP_READY && !file_exists(cache, "custom_../evil.json") &&
          !file_exists(cache, "../evil.json"), "an unsafe custom id is shown, never written: %s", why);

    // 4. past the table: no network -> unknown
    const int next = KRUNKER_OFFICIAL_MAP_COUNT;
    krunker_map_source_set_fetch(NULL);
    CHECK(resolve(next, NULL, "", &out, why, sizeof(why)) == KRUNKER_MAP_UNKNOWN && strstr(why, "newer"), "past the table, offline: %s", why);
    // ... with the network: GET <API>/maps/<index>, pending until it answers, then cached
    krunker_map_source_set_fetch(fake_fetch);
    KrunkerMapRequest r;
    krunker_map_request_begin(&r, next, NULL, "");
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_PENDING, "past the table: pending (%s)", why);
    char want[128];
    snprintf(want, sizeof(want), "%s/maps/%d", KRUNKER_MAPS_API_URL, next);
    CHECK(!strcmp(g_net.url, want), "GET %s (want %s)", g_net.url, want);
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_PENDING, "still pending");
    char body[512];
    snprintf(body, sizeof(body), "{\"data\":%s}", k_tiny_map);
    answer(200, body);
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_READY && out, "past the table: downloaded (%s)", why);
    char name[64];
    snprintf(name, sizeof(name), "official_%d.json", next);
    CHECK(file_exists(cache, name), "downloaded map cached as %s", name);
    const int calls = g_net.calls;
    CHECK(resolve(next, NULL, "", &out, why, sizeof(why)) == KRUNKER_MAP_READY && g_net.calls == calls, "a downloaded map is not fetched twice");
    // 3. a community map by id that is nowhere else: GET <API>/maps/<id>, pending, then cached as custom_<id>.json
    krunker_map_request_begin(&r, 0, NULL, "555777");
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_PENDING, "community id by GET: pending (%s)", why);
    snprintf(want, sizeof(want), "%s/maps/555777", KRUNKER_MAPS_API_URL);
    CHECK(!strcmp(g_net.url, want), "community id: GET %s (want %s)", g_net.url, want);
    answer(200, body);
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_READY && out, "community id downloaded (%s)", why);
    snprintf(name, sizeof(name), "custom_555777.json");
    CHECK(file_exists(cache, name), "downloaded community map cached as %s", name);
    CHECK(resolve(0, NULL, "555777", &out, why, sizeof(why)) == KRUNKER_MAP_READY && g_net.calls == calls + 1,
          "a downloaded community map is not fetched twice: %s", why);
    // a failed download
    krunker_map_request_begin(&r, next + 1, NULL, "");
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_PENDING, "next+1 pending");
    answer(404, "{\"data\":null,\"error\":\"not found\"}");
    CHECK(krunker_map_request_poll(&r, &out, why, sizeof(why)) == KRUNKER_MAP_UNKNOWN && strstr(why, "HTTP 404"), "404: %s", why);
    // a cancelled download's late answer is ignored
    krunker_map_request_begin(&r, next + 2, NULL, "");
    krunker_map_request_poll(&r, &out, why, sizeof(why));
    krunker_map_request_cancel(&r);
    answer(200, body);
    snprintf(name, sizeof(name), "official_%d.json", next + 2);
    CHECK(!file_exists(cache, name), "a cancelled download stores nothing");
    g_net.refuse = 1;
    CHECK(resolve(next + 3, NULL, "", &out, why, sizeof(why)) == KRUNKER_MAP_UNKNOWN && strstr(why, "could not be started"), "refused: %s", why);
    CHECK(resolve(-1, NULL, "", &out, why, sizeof(why)) == KRUNKER_MAP_UNKNOWN && strstr(why, "no map"), "no map: %s", why);
}

int main(void) {
    char cache[1024];
    const char *tmp = getenv("TMPDIR");
    snprintf(cache, sizeof(cache), "%s/kn-krunker-maps-test-XXXXXX", tmp && tmp[0] ? tmp : "/tmp");
    if (!mkdtemp(cache)) {
        perror("mkdtemp");
        return 1;
    }
    test_setenv("KRUNKNATIVE_KRUNKER_MAP_CACHE", cache, 1);
    CHECK(!strcmp(krunker_map_cache_dir(), cache), "cache dir %s", krunker_map_cache_dir());
    test_table();
    test_spawns();
    test_slot_not_index();
    test_requests(cache);
    // clean up only what this test made
    char path[1200];
    const char *made[] = {"custom_123456.json", "custom_987.json", "custom_555777.json", NULL};
    for (int i = 0; made[i]; i++) {
        snprintf(path, sizeof(path), "%s/%s", cache, made[i]);
        remove(path);
    }
    for (int k = 0; k < 4; k++) {
        snprintf(path, sizeof(path), "%s/official_%d.json", cache, KRUNKER_OFFICIAL_MAP_COUNT + k);
        remove(path);
    }
    rmdir(cache);
    printf("%s: %d checks, %d failures\n", g_fail ? "krunker_maps_test FAILED" : "Test OK", g_pass + g_fail, g_fail);
    return g_fail ? 1 : 0;
}
